quota_scripts.script:
function httpErr(e) {
  var m = e && e.message ? String(e.message) : String(e);
  if (m.indexOf("HTTP ") === 0) return m;
  if (m.indexOf("JSON parse: ") === 0) return "Parse: " + m.slice(12);
  return "Network: " + m;
}
function intVal(v) {
  return typeof v === "number" && Number.isInteger(v) ? v : null;
}
function msToIso(ms) {
  try {
    var iso = new Date(ms).toISOString();
  } catch (e) {
    return null;
  }
  if (ms % 1000 === 0) return iso.slice(0, 19) + "+00:00";
  return iso.slice(0, 23) + "+00:00";
}
var body;
try {
  body = http.get("https://api.minimax.io/v1/api/openplatform/coding_plan/remains", {
    "Authorization": "Bearer " + ctx.apiKey,
    "Content-Type": "application/json"
  });
} catch (e) {
  return { success: false, error: httpErr(e) };
}
if (body == null || typeof body !== "object" || Array.isArray(body)) body = {};
if (body.base_resp !== undefined) {
  var br = body.base_resp;
  var code = br == null ? null : intVal(br.status_code);
  if (code === null) code = -1;
  if (code !== 0) {
    var msg = br != null && typeof br.status_msg === "string" ? br.status_msg : "Unknown";
    return { success: false, error: "API error (code " + code + "): " + msg };
  }
}
var tiers = [];
if (Array.isArray(body.model_remains)) {
  var item = null;
  for (var i = 0; i < body.model_remains.length; i++) {
    var m = body.model_remains[i];
    if (m != null && typeof m.model_name === "string" && m.model_name === "general") {
      item = m;
      break;
    }
  }
  if (item != null) {
    var pct5 = typeof item.current_interval_remaining_percent === "number"
      ? item.current_interval_remaining_percent
      : null;
    if (pct5 !== null) {
      var et = intVal(item.end_time);
      tiers.push({
        name: "five_hour",
        utilization: 100.0 - pct5,
        resets_at: et === null ? null : msToIso(et)
      });
    }
    var ws = intVal(item.current_weekly_status);
    var wpct = typeof item.current_weekly_remaining_percent === "number"
      ? item.current_weekly_remaining_percent
      : null;
    if ((ws === 1 || ws === 2) && wpct !== null) {
      var wet = intVal(item.weekly_end_time);
      var totalC = typeof item.current_weekly_total_count === "number"
        ? item.current_weekly_total_count
        : null;
      var limit = totalC !== null && totalC > 0.0 ? totalC : null;
      var remaining = null;
      if (limit !== null) {
        var uc = typeof item.current_weekly_usage_count === "number"
          ? item.current_weekly_usage_count
          : null;
        if (uc !== null) remaining = Math.max(limit - uc, 0.0);
      }
      tiers.push({
        name: "weekly_limit",
        utilization: 100.0 - wpct,
        resets_at: wet === null ? null : msToIso(wet),
        limit: limit,
        remaining: remaining
      });
    }
  }
}
return {
  success: true,
  error: null,
  balance: null,
  coding_plan: { level: null, tiers: tiers }
};
